function reqCompra(array$s,string$path,?array$data=null):array{$h=curl_init('http://127.0.0.1:18079'.$path);curl_setopt_array($h,[CURLOPT_RETURNTRANSFER=>true,CURLOPT_HEADER=>true,CURLOPT_COOKIEJAR=>$s['jar'],CURLOPT_COOKIEFILE=>$s['jar'],CURLOPT_TIMEOUT=>25]);if($data!==null){curl_setopt($h,CURLOPT_POST,true);curl_setopt($h,CURLOPT_POSTFIELDS,$data);}$r=curl_exec($h);if($r===false)throw new RuntimeException(curl_error($h));$n=curl_getinfo($h,CURLINFO_HEADER_SIZE);return['code'=>curl_getinfo($h,CURLINFO_RESPONSE_CODE),'body'=>substr($r,$n),'headers'=>substr($r,0,$n)];}
function sessionCompra(bool$download):array{global$pdo,$sid,$prefix,$users,$sessions,$root;$email=$prefix.'-'.count($users).'@example.test';$pass='QA-pull-only-'.bin2hex(random_bytes(12));$pdo->prepare("INSERT INTO usuarios(nombre,email,password,rol,activo,recibe_mails,debe_cambiar_password) VALUES(?,?,?,'usuario',1,0,0)")->execute([$prefix,$email,password_hash($pass,PASSWORD_DEFAULT)]);$id=(int)$pdo->lastInsertId();$users[]=$id;$pdo->prepare("INSERT INTO usuario_sector(usuario_id,sector_id,rol_sector,puede_ver,puede_editar,puede_aprobar,puede_descargar) VALUES(?,?,'responsable',1,1,1,?)")->execute([$id,$sid,(int)$download]);$s=['id'=>$id,'jar'=>tempnam($root.'/logs','qa_cmp_cookie_')];$sessions[]=$s;$r=reqCompra($s,'/php/login.php');preg_match('/name="csrf" value="([^"]+)"/',$r['body'],$m);$s['csrf']=$m[1]??'';$r=reqCompra($s,'/php/login.php',['csrf'=>$s['csrf'],'email'=>$email,'password'=>$pass]);ckCompra($r['code']===302,'Responsable QA inicia sesión');return$s;}
function purchaseCompra(array$s,?int$form=null):int{global$pdo,$sid,$prefix,$purchaseIds;$pdo->prepare("INSERT INTO compras(sector_id,codigo,sector,descripcion,cantidad,formulario_registro_id,creado_por,actualizado_por) VALUES(?,?,'Compras',?,1,?,?,?)")->execute([$sid,$prefix.'-'.bin2hex(random_bytes(3)),$prefix,$form,$s['id'],$s['id']]);$id=(int)$pdo->lastInsertId();$purchaseIds[]=$id;return$id;}
function attachmentCompra(int$cid,string$route,int$stage=1,string$type='Pedido de compra'):int{global$pdo,$yes;$pdo->prepare('INSERT INTO compras_documentos(compra_id,etapa,nombre_archivo,ruta_archivo,tipo_documento,creado_por) VALUES(?,?,?,?,?,?)')->execute([$cid,$stage,basename($route),$route,$type,$yes['id']]);return(int)$pdo->lastInsertId();}
function stageCompra(array$s,int$cid,int$stage,string$type,array$data=[]):array{global$pdf;$p=['csrf'=>$s['csrf'],'accion'=>'documento_etapa','compra_id'=>$cid,'etapa_doc'=>$stage,'tipo_documento'=>$type,'archivo_etapa'=>new CURLFile($pdf,'application/pdf','qa-etapa.pdf')];foreach($data as$k=>$v)$p['datos['.$k.']']=$v;return reqCompra($s,'/php/compras.php',$p);}
