 $r=reqCompra($yes,'/php/compras.php',['csrf'=>$yes['csrf'],'accion'=>'actualizar_documento','documento_id'=>$sharedDoc,'archivo_reemplazo'=>new CURLFile($pdf,'application/pdf','qa-reemplazo.pdf')]);ckCompra($r['code']===303&&is_file($root.'/uploads/'.$route),'Reemplazo conserva archivo compartido con otra compra y papelera');
 $r=reqCompra($yes,'/php/compras.php',['csrf'=>$yes['csrf'],'accion'=>'eliminar','id'=>$cid]);ckCompra($r['code']===303&&is_file($root.'/uploads/'.$route),'Eliminar última compra compartida conserva referencia en papelera/versiones');
